#!/usr/bin/env python3
"""Render commands.toml into ledger/_commands.py (the CLI's dispatch table)."""

from __future__ import annotations

import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def main() -> None:
    spec = tomllib.loads((ROOT / "commands.toml").read_text(encoding="utf-8"))
    lines = [
        "# GENERATED by tools/gen_cli.py from commands.toml. Do not edit: ./verify.sh",
        "# regenerates this file. Register commands in commands.toml.",
        "",
        "COMMANDS: dict[str, tuple[str, str]] = {",
    ]
    for cmd in spec["command"]:
        lines.append(f"    {cmd['name']!r}: ({cmd['handler']!r}, {cmd['help']!r}),")
    lines.append("}")
    (ROOT / "ledger" / "_commands.py").write_text("\n".join(lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
